R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
mkdir -p $R/sb_ph2fix/prompts $R/sb_ph2fix/out $R/sb_ktchk/work
echo  | base64 -d > $R/sb_ph2fix/prompts/sb_ph2fix.md
printf 'sb_ph2fix\n' >> $R/sb_queue/queue.txt
cp $R/sb_cursor_probe/AGENTS.md $R/sb_ktchk/AGENTS.md
echo  | base64 -d > $R/sb_ktchk/PROMPT.md
cd $R/sb_ktchk && tmux new-session -d -s sb_ktchk "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
echo "@@FILE FIX2_REPORT.md"; cat $R/sb_ktfix2/out/FIX2_REPORT.md
echo "@@FILE PH2GATE_REPORT.md"; cat $R/sb_ph2gate/out/PH2GATE_REPORT.md
echo "@@FILE PHFIX_NOTES.md"; cat $R/sb_phfix/out/PHFIX_NOTES.md 2>/dev/null || cat $R/sb_phfix/PHFIX_NOTES.md
echo "@@FILE phrase_BARS.json"; cat $R/sb_phfix/sb_mask_phrase/out/BARS.json
echo "@@FILE FIX4_REPORT.md"; cat $R/sb_rlfix4/out/FIX4_REPORT.md
echo "@@FILE SHA256S.txt"; cat $R/sb_ktfix2/out/sb_ktfix2.tar.sha256 $R/sb_ph2gate/out/sb_ph2gate.tar.sha256 $R/sb_phfix/out/sb_phfix.tar.sha256 $R/sb_rlfix4/out/SHA256SUMS 2>&1 | head -5
